'use strict';
(()=>{
 const normalize=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
 const skills=[
 {name:'Microsoft Azure',re:/\b(?:azure|az-900)\b/,level:1,weight:3,confidence:"High",evidence:"Working with Azure since 2019; Microsoft Certified: Azure Fundamentals (AZ-900).",link:'#certificados',category:'Cloud'},
 {name:'.NET / C#',re:/(?:\.net|dotnet|c#|csharp)/,level:.95,weight:2,confidence:"High",evidence:"Developing .NET APIs and services at Reply since 2019.",link:'#experiencia',category:'Backend'},
 {name:'React',re:/\breact(?:js|\.js)?\b/,level:.9,weight:1,confidence:"High",evidence:"React interfaces and hooks in fullstack development.",link:'#experiencia',category:'Frontend'},
 {name:'Vue / Nuxt',re:/\b(?:vue|nuxt)(?:js|\.js)?\b/,level:.9,weight:1,confidence:"High",evidence:"Developing Vue.js and Nuxt interfaces.",link:'#experiencia',category:'Frontend'},
 {name:'Node.js',re:/\bnode(?:\.?js)?\b/,level:.85,weight:1,confidence:"High",evidence:"Backend development with Node.js in my senior role.",link:'#experiencia',category:'Backend'},
 {name:'NestJS',re:/\bnest(?:js|\.js)?\b/,level:.6,weight:1,confidence:"Medium",evidence:"NestJS is a declared skill; depth to be discussed in a technical interview.",link:'#certificados',category:'Backend'},
 {name:'APIs REST',re:/\b(?:apis?|rest|restful)\b/,level:.95,weight:2,confidence:"High",evidence:"Developing and integrating APIs and services across applications.",link:'#pratica',category:"Integrations"},
 {name:"Kafka / Events",re:/\b(?:kafka|eventos?|events?|event.driven|mensageria)\b/,level:.85,weight:2,confidence:"Medium",evidence:"Declared experience in event-driven architecture and Kafka messaging.",link:'#pratica',category:"Integrations"},
 {name:'Webhooks',re:/\bwebhooks?\b/,level:.85,weight:1,confidence:"Medium",evidence:"Developing webhooks for system integration.",link:'#pratica',category:"Integrations"},
 {name:"SQL / Data",re:/\b(?:sql|postgresql|oracle|bancos? de dados|database)\b/,level:.95,weight:1,confidence:"High",evidence:"Working with SQL Server since 2016, with PostgreSQL and Oracle experience.",link:'#experiencia',category:"Data"},
 {name:"Claude Code and Codex",re:/\b(?:claude|codex|agentes? de (?:codigo|ia)|inteligencia artificial|ia|ai)\b/,level:.85,weight:1,confidence:"Medium",evidence:"Using Claude Code and Codex for specification-driven development, including review and validation.",link:'#ia',category:"AI & SDD"},
 {name:'SDD / OpenSpec',re:/\b(?:sdd|openspec|spec.driven|especificacoes|specifications)\b/,level:.85,weight:1,confidence:"Medium",evidence:"OpenSpec: proposals, delta specs, design, tasks and acceptance scenario verification.",link:'#ia',category:"AI & SDD"},
 {name:'Angular',re:/\bangular\b/,level:.8,weight:1,confidence:"High",evidence:"Angular is part of my declared frontend experience.",link:'#certificados',category:'Frontend'},
 {name:"English",re:/\b(?:ingles|english)\b/,level:.9,weight:1,confidence:"Medium",evidence:"Advanced English proficiency declared in the resume.",link:'#perguntas',category:"Communication"},
 {name:'AWS',re:/\b(?:aws|lambda|s3|sqs)\b/,level:.75,weight:1,confidence:"Medium",evidence:"Declared AWS experience: Lambda, S3 and SQS. Preparatory course documented; scope of use to be discussed in an interview.",link:'#inicio',category:'Cloud'},
 ...[['Kubernetes',/\b(?:kubernetes|k8s)\b/],['Docker',/\bdocker\b/],['Terraform',/\bterraform\b/],['Python',/\bpython\b/],["Formal leadership",/\b(?:lideranca|leadership|tech lead|gestao de pessoas)\b/]].map(([name,re])=>({name,re,level:name==="AWS in production"?.25:0,weight:1,confidence:"To confirm",evidence:name==="AWS in production"?"Documented AWS preparatory course; production experience to be confirmed.":"No detailed evidence in the current resume; confirm in an interview.",link:'#certificados',category:"To confirm"}))
 ];
 const input=document.querySelector('#job'),out=document.querySelector('#fit-output');
 const draft="Senior Fullstack Developer focused on Azure\nWe are looking for experience with Microsoft Azure, C# and .NET, REST APIs, React or Vue and SQL Server. Event-driven integrations with Kafka and webhooks. AI-assisted development using Claude Code and Codex, SDD and OpenSpec.\nDesirable: Kubernetes in production.";
 const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
 function analyze(){document.querySelector('#fit-empty').hidden=true;out.hidden=false;out.replaceChildren();const text=normalize(input.value);const results=skills.filter(s=>s.re.test(text)).map(s=>{const sentences=text.split(/\n|[!;]|\.(?=\s|$)/).filter(x=>s.re.test(x));const optional=sentences.every(x=>/desejavel|diferencial|opcional|nice.to.have|desirable|preferred|optional/.test(x));return {...s,optional,w:s.weight*(optional?.5:1)};});
 if(!results.length){out.append(el('p','empty-match',"Enter requirements or technologies in the description to see the fit."));document.querySelector('#analysis-steps').textContent="Waiting for recognized requirements.";return;}
 const total=results.reduce((a,s)=>a+s.w,0),score=Math.round(results.reduce((a,s)=>a+s.w*s.level,0)/total*100),high=results.filter(s=>s.confidence==="High").length;
 const summary=el('div','fit-summary');const ring=el('div','score-ring');ring.style.setProperty('--score',score+'%');ring.setAttribute('role','img');ring.setAttribute('aria-label',`Estimated fit: ${score} out of 100`);const inside=el('div');inside.append(el('strong','',score),el('span','','/100 FIT'));ring.append(inside);
 const copy=el('div','score-copy');copy.append(el('span','recommend-tag',"● ESTIMATED FIT"),el('h3','',score>=75?"Good alignment for a technical conversation":score>=45?"Partial alignment with the role":"Explore the requirements in an interview"),el('span','confidence-tag',`HIGH CONFIDENCE IN ${high} OF ${results.length} REQUIREMENTS`));
 const confirmed=results.filter(s=>s.level>=.8).slice(0,4).map(s=>s.name),pending=results.filter(s=>s.level<.8).map(s=>s.name);copy.append(el('p','',`${confirmed.length?'Highlights: '+confirmed.join(', ')+'. ':''}${pending.length?'To confirm: '+pending.join(', ')+'.':''}`));summary.append(ring,copy);out.append(summary);
 const chart=el('div','category-chart');chart.append(el('span','eyebrow',"COVERAGE BY AREA"));const categories=[...new Set(results.map(s=>s.category))];categories.forEach(c=>{const rs=results.filter(s=>s.category===c),v=Math.round(rs.reduce((a,s)=>a+s.level*s.w,0)/rs.reduce((a,s)=>a+s.w,0)*100);const row=el('div','category-row'),track=el('span','category-track'),fill=el('span');fill.style.width=v+'%';track.append(fill);row.append(el('span','',c),track,el('b','',v+'%'));chart.append(row);});out.append(chart);
 const table=el('table','fit-table'),thead=el('thead'),hr=el('tr');["Requirement","Level","Evidence","Confidence"].forEach(t=>hr.append(el('th','',t)));thead.append(hr);const tbody=el('tbody');results.forEach(s=>{const tr=el('tr'),req=el('td');req.append(el('b','',s.name),el('small','',`${s.optional?'DESIRABLE':'REQUIREMENT'} · WEIGHT ${s.w}`));const level=el('td'),bars=el('div','level-bars');bars.setAttribute('aria-label',`${Math.round(s.level*100)}% estimated coverage`);for(let i=0;i<4;i++)bars.append(el('i',i<Math.round(s.level*4)?'filled':''));level.append(bars,el('small','',s.level>=.98?"Expertise":s.level>=.8?"Strong":s.level>0?"Partial":"To confirm"));const evidence=el('td','evidence-text',s.evidence),link=el('a','',"View evidence ↗");link.href=s.link;evidence.append(link);tr.append(req,level,evidence,el('td',s.confidence==="High"?'confidence-high':'confidence-medium',s.confidence));tbody.append(tr);});table.append(thead,tbody);const scroll=el('div','fit-table-scroll');scroll.append(table);out.append(scroll);
 out.append(el('p','micro methodology',"Score = weighted average of declared coverage. Azure has weight 3 for experience since 2019 and certification; .NET, REST and Kafka have weight 2. Desirable requirements carry half the weight. Unrecognized requirements need human assessment."));
 document.querySelector('#analysis-steps').textContent=`✓ ${results.length} recognized requirements (${results.filter(s=>!s.optional).length} core · ${results.filter(s=>s.optional).length} desirable)\n✓ Compared with experience and credentials\n✓ Weighted score updated in real time`;
 }
 document.querySelector('#example').addEventListener('click',()=>{input.value=draft;analyze();input.focus();});document.querySelector('#fit-form').addEventListener('submit',e=>{e.preventDefault();analyze();});input.addEventListener('input',analyze);input.value=draft;analyze();
})();
